static inline void ds_font_unpack_atlas(uint8_t *dest, size_t dest_size) {
    if (dest == nullptr || dest_size < DS_FONT_ATLAS_RAW_SIZE) return;
    size_t out_idx = 0;
    for (size_t in_idx = 0; in_idx + 1 < DS_FONT_ATLAS_RLE_SIZE && out_idx < dest_size; in_idx += 2) {
        uint8_t count = ds_font_atlas_rle[in_idx];
        uint8_t val = ds_font_atlas_rle[in_idx + 1];
        size_t run = (out_idx + count <= dest_size) ? count : (dest_size - out_idx);
        memset(dest + out_idx, val, run);
        out_idx += run;
    }
}
